    public MainWindow() { InitializeComponent(); PresetBox.ItemsSource = new[] { "Sine", "Cosine", "Tangent", "Parametric", "ORBIT", "PULSE", "SPIN", "ORBIT + SPIN" }; foreach(var slider in new[]{SpeedSlider,FrequencySlider,VolumeSlider}) { slider.PreviewMouseDown += AuthorSlider_MouseDown; slider.PreviewMouseUp += AuthorSlider_MouseUp; } animationTimer.Tick += (_, _) => { time.Update(1.0/60); var result=automation.Evaluate(time.Time,document.Parameters.Items); if(result.Error is not null) { StatusText.Text="ERROR: "+result.Error; StatusText.Foreground=Brushes.Salmon; } foreach(var p in document.Parameters.Items) if(result.Values.TryGetValue(p.Name,out var value)) p.EffectiveValue=value; Refresh(false); }; Loaded += (_, _) => { loaded = true; Refresh(true); savedState = Snapshot(); animationTimer.Start(); }; }
    EquationEntry Selected => document.Selected ?? document.Equations[0];
