    string Snapshot() => AuthoredStateCodec.Serialize(State());
    void Reconcile() { document.ReconcileParameters(procedural.Objects.SelectMany(o=>o.OutputBindings).Where(b=>b.ParsedExpression is not null).SelectMany(b=>b.ParsedExpression!.Parameters)); foreach(var p in document.Parameters.Items) p.Normalize(); }
    void Author(Action action, bool rebuild=true) { if(restoring)return; var before=Snapshot(); action(); if(rebuild)Reconcile(); var after=Snapshot(); if(!AuthoredStateCodec.Equal(before,after)){history.Record(before); MarkDirty();} Refresh(rebuild); }
    void BeginDrag() { if(!loaded||restoring)return; _dragBefore ??= Snapshot(); }
    string? _dragBefore;
    void EndDrag() { if(_dragBefore is null)return; var after=Snapshot();if(!AuthoredStateCodec.Equal(_dragBefore,after)){history.Record(_dragBefore);MarkDirty();} _dragBefore=null; }
    void MarkDirty() { DirtyText.Text="* UNSAVED"; Title="Equation Synth *"; }
    void RecomputeDirty() { var dirty=!AuthoredStateCodec.Equal(savedState,Snapshot());DirtyText.Text=dirty?"* UNSAVED":"";Title=dirty?"Equation Synth *":"Equation Synth";StatusBarText.Text=$"{document.Equations.Count} equation{(document.Equations.Count==1?"":"s")} | {document.Parameters.Items.Count} parameter{(document.Parameters.Items.Count==1?"":"s")} | t={time.Time:0.000} | Audio: {(mixerAudio.IsPlaying?mixerAudio.Status:audio.Status)}"; }
    void Refresh(bool rebuildUi) { if(rebuildUi){BuildEquationList();BuildProceduralPanel();BuildParameters();UpdateLayerTables();} TimeText.Text=$"t = {time.Time:0.000}";SpeedText.Text=$"{SpeedSlider.Value:0.0}x";FrequencyText.Text=$"{FrequencySlider.Value:0} Hz";VolumeText.Text=$"{VolumeSlider.Value:0.00}";AudioStatusText.Text=$"{(mixerAudio.IsPlaying?mixerAudio.Status:audio.Status)} · {AudioEngine.SampleRate} Hz · {WaveformEngine.SampleCount} samples"; DrawGraph();DrawWave();DrawProcedural();RecomputeDirty(); }
    void UpdateLayerTables(){foreach(var layer in document.Equations)if(layer.ParsedExpression is not null)layerTables[layer.Id]=waves.Generate(layer.ParsedExpression,time.Time,document.Parameters.Values);mixer.Reconcile(document.Equations,layerTables);}
    double[] MasterTable(){UpdateLayerTables();var enabled=document.Equations.Where(e=>MixerMath.IsAudible(e,document.Equations.Any(x=>x.IsSolo))).ToList();var table=new double[WaveformEngine.SampleCount];foreach(var layer in enabled)if(layerTables.TryGetValue(layer.Id,out var source))for(var i=0;i<table.Length;i++)table[i]+=source[i]*layer.AudioVolume;var scale=Math.Max(1,enabled.Count);for(var i=0;i<table.Length;i++)table[i]=Math.Tanh(table[i]/Math.Sqrt(scale)*mixer.MasterGain*1.4);return table;}
    void BuildEquationList(){EquationsPanel.Children.Clear();foreach(var e in document.Equations){var card=new StackPanel{Margin=new Thickness(2),Background=e.IsSelected?new SolidColorBrush(Color.FromRgb(35,67,82)):Brushes.Transparent};var row=new DockPanel();var eye=new CheckBox{IsChecked=e.IsVisible,Content="◉",Width=28,Tag=e};eye.Click+=(s,x)=>Author(()=>e.IsVisible=eye.IsChecked==true,false);var audioEnabled=new CheckBox{IsChecked=e.IsAudioEnabled,Content="AUDIO",Tag=e};audioEnabled.Click+=(s,x)=>Author(()=>e.IsAudioEnabled=audioEnabled.IsChecked==true,false);var mute=new CheckBox{IsChecked=e.IsMuted,Content="MUTE",Tag=e};mute.Click+=(s,x)=>Author(()=>e.IsMuted=mute.IsChecked==true,false);var solo=new CheckBox{IsChecked=e.IsSolo,Content="SOLO",Tag=e};solo.Click+=(s,x)=>Author(()=>e.IsSolo=solo.IsChecked==true,false);var name=new TextBlock{Text=e.DisplayName,Foreground=Brushes.White,Margin=new Thickness(4)};var del=new Button{Content="×",Tag=e};del.Click+=(s,x)=>Author(()=>{document.Select(e);document.RemoveSelected();});row.Children.Add(eye);row.Children.Add(new Border{Width=12,Height=12,Background=Brush(e.ColorHex),Margin=new Thickness(4)});row.Children.Add(name);row.Children.Add(audioEnabled);row.Children.Add(mute);row.Children.Add(solo);row.Children.Add(del);card.Children.Add(row);var controls=new StackPanel{Orientation=Orientation.Horizontal};controls.Children.Add(new TextBlock{Text="Hz",Margin=new Thickness(2)});controls.Children.Add(LayerSlider(e,20,2000,e.AudioFrequency,(v)=>e.AudioFrequency=v));controls.Children.Add(new TextBlock{Text="Vol",Margin=new Thickness(2)});controls.Children.Add(LayerSlider(e,0,1,e.AudioVolume,(v)=>e.AudioVolume=v));controls.Children.Add(new TextBlock{Text="Pan",Margin=new Thickness(2)});controls.Children.Add(LayerSlider(e,-1,1,e.AudioPan,(v)=>e.AudioPan=v));controls.Children.Add(new TextBlock{Text="A/D/S/R",Margin=new Thickness(2)});controls.Children.Add(EnvelopeSlider(e,0,2,e.Envelope.Attack,v=>e.Envelope.Attack=v));controls.Children.Add(EnvelopeSlider(e,0,2,e.Envelope.Decay,v=>e.Envelope.Decay=v));controls.Children.Add(EnvelopeSlider(e,0,1,e.Envelope.Sustain,v=>e.Envelope.Sustain=v));controls.Children.Add(EnvelopeSlider(e,0,2,e.Envelope.Release,v=>e.Envelope.Release=v));card.Children.Add(controls);row.MouseLeftButtonDown+=(s,x)=>{document.Select(e);EquationBox.Text=e.ExpressionText;Refresh(true);};EquationsPanel.Children.Add(card);} }
    Slider LayerSlider(EquationEntry e,double min,double max,double value,Action<double> assign){var slider=new Slider{Minimum=min,Maximum=max,Value=value,Width=70,Tag=e};slider.PreviewMouseDown+=(s,x)=>BeginDrag();slider.PreviewMouseUp+=(s,x)=>EndDrag();slider.ValueChanged+=(s,x)=>{if(!restoring){assign(slider.Value);UpdateLayerTables();Refresh(false);}};return slider;}
